import json
rows = json.loads(context)
daily = {}
for r in rows:
    d = daily.setdefault(r['record_date'], {'deposits': 0, 'withdrawals': 0})
    name = r['account_type'].lower()
    amount = int(r['open_today_bal'])
    if 'deposit' in name:
        d['deposits'] += amount
    elif 'withdrawal' in name:
        d['withdrawals'] += amount
answer = sum(v['withdrawals'] for v in daily.values() if v['deposits'] < v['withdrawals'])
print(FINAL(str(answer)))
